// Generated by AI (UnitTest MCP)
//! Facade over the design-item bridge (ADR-0023): register an ADR for review,
//! read the Design Board, and the human accept/reject decision that completes
//! design work without code conformance.

use crate::design::{
    design_id_from_path, resembling_deciders, DesignActionKind, DesignItem, DesignMetadata,
    DesignPromotionStatus, DesignStatus,
};
use crate::{now_unix, Lodestar, LodestarError, Result};

impl Lodestar {
    /// Register an ADR as a design item under review. It is *proposed* (tainted)
    /// until a human decides it: invisible to `next_task` and the executive
    /// board, present on the Design Board.
    pub fn register_design(
        &self,
        adr_path: &str,
        title: &str,
        summary: &str,
        proposed_by: Option<&str>,
    ) -> Result<DesignItem> {
        let adr_path = adr_path.replace('\\', "/");
        let id = design_id_from_path(&adr_path);
        self.store
            .register_design_item(&id, &adr_path, title, summary, proposed_by, now_unix())
    }

    /// Reconcile structured repository ADR metadata without inferring or
    /// scheduling implementation work. Existing durable decisions always win.
    pub fn reconcile_designs(&self, entries: &[DesignMetadata]) -> Result<Vec<DesignItem>> {
        let now = now_unix();
        let mut reconciled = Vec::with_capacity(entries.len());
        for entry in entries {
            let adr_path = entry.adr_path.trim().replace('\\', "/");
            if adr_path.is_empty() || entry.title.trim().is_empty() {
                return Err(LodestarError::Invalid(
                    "reconciled ADR metadata requires a path and title".to_string(),
                ));
            }
            reconciled.push(self.store.reconcile_design_item(
                &DesignMetadata {
                    adr_path,
                    title: entry.title.trim().to_string(),
                    summary: entry.summary.trim().to_string(),
                    status: entry.status,
                    proposed_by: entry.proposed_by.clone(),
                },
                now,
            )?);
        }
        Ok(reconciled)
    }

    /// The actionable Design Board: proposed decisions plus accepted designs
    /// whose implementation promotion is pending or retryable.
    pub fn design_board(&self) -> Result<Vec<DesignItem>> {
        self.store.actionable_design_items()
    }

    /// Every design item (durable audit view), or those in one status. Retired
    /// and deferred records are omitted unless explicitly included.
    pub fn list_design_items(
        &self,
        status: Option<DesignStatus>,
        include_retired: bool,
        include_deferred: bool,
    ) -> Result<Vec<DesignItem>> {
        self.store
            .list_design_items(status, include_retired, include_deferred)
    }

    /// Park a proposed design without deciding it (ADR-0077).
    pub fn defer_design(&self, id: &str, human: &str, reason: &str) -> Result<DesignItem> {
        let human = human.trim();
        let reason = reason.trim();
        if reason.is_empty() {
            return Err(LodestarError::Invalid(
                "deferring a design requires a reason".to_string(),
            ));
        }
        self.load_for_decision(id, human)?;
        self.store.defer_design_item(id, human, reason, now_unix())
    }

    /// Return a deferred proposal to the working Design Board (ADR-0077).
    pub fn resume_design(&self, id: &str, human: &str, reason: &str) -> Result<DesignItem> {
        let human = human.trim();
        if human.is_empty() {
            return Err(LodestarError::Invalid(
                "resuming a design requires the person doing it".to_string(),
            ));
        }
        if reason.trim().is_empty() {
            return Err(LodestarError::Invalid(
                "resuming a design requires a reason".to_string(),
            ));
        }
        self.store
            .resume_design_item(id, human, reason.trim(), now_unix())
    }

    /// Immutable attributed defer/resume/reject/retire history (ADR-0077).
    pub fn design_action_history(&self, id: &str) -> Result<Vec<crate::DesignAction>> {
        self.store.design_action_history(id)
    }

    /// Apply one attributed backlog act to every named design atomically.
    pub fn apply_design_actions(
        &self,
        ids: &[String],
        action: DesignActionKind,
        human: &str,
        reason: &str,
    ) -> Result<Vec<DesignItem>> {
        let human = human.trim();
        if human.is_empty() {
            return Err(LodestarError::Invalid(
                "a design action requires the person doing it".to_string(),
            ));
        }
        let reason = reason.trim();
        if reason.is_empty() {
            return Err(LodestarError::Invalid(
                "a design action requires a reason".to_string(),
            ));
        }
        if matches!(action, DesignActionKind::Defer | DesignActionKind::Reject) {
            for id in ids {
                self.load_for_decision(id, human)?;
            }
        }
        self.store
            .apply_design_actions(ids, action, human, reason, now_unix())
    }

    /// Retire a design record: an explicit, attributed human act (ADR-0042).
    ///
    /// This exists because `reconcile_designs` keys on the ADR path, so renaming
    /// an ADR registers a new record and orphans the old one permanently. The
    /// tempting alternative — retiring any design whose file is missing — is
    /// refused by design: several worktrees on different branches share one
    /// database, so a missing file is routine and retiring on it would delete
    /// live decisions on someone else's branch.
    ///
    /// Retiring is not deleting (ADR-0019): the row keeps its id, path,
    /// decision, decider, and materialization history.
    pub fn retire_design(&self, id: &str, human: &str, reason: &str) -> Result<DesignItem> {
        let human = human.trim();
        if human.is_empty() {
            return Err(LodestarError::Invalid(
                "retiring a design requires the person doing it".to_string(),
            ));
        }
        let reason = reason.trim();
        if reason.is_empty() {
            return Err(LodestarError::Invalid(
                "retiring a design requires a reason".to_string(),
            ));
        }
        self.store.retire_design_item(id, human, reason, now_unix())
    }

    /// Record that an accepted design has been replaced by another (ADR-0050).
    ///
    /// Supersession is not retirement and not rejection. Retiring says the
    /// record should not have existed; rejecting says the decision was refused.
    /// Superseding says the decision was made, it held, and something better
    /// replaced it — so the row stays `accepted` and gains a link to its
    /// successor, exactly as `Goal::superseded_by` already works.
    ///
    /// Never inferred from an ADR's `Superseded by <ref>` prose. Deriving the
    /// link from the file would repeat ADR-0047's mistake of a file telling the
    /// ledger something nobody is recorded as deciding; `make design-audit`
    /// reports the mismatch until a person runs this.
    pub fn supersede_design(
        &self,
        id: &str,
        superseded_by: &str,
        human: &str,
    ) -> Result<DesignItem> {
        let human = human.trim();
        if human.is_empty() {
            return Err(LodestarError::Invalid(
                "superseding a design requires the person doing it".to_string(),
            ));
        }
        self.store
            .supersede_design_item(id, superseded_by.trim(), human, now_unix())
    }

    /// Recorded decider labels that resemble `human` closely enough to be a
    /// typo for one of them (see [`resembling_deciders`]).
    ///
    /// Advisory, and returned alongside the act that wrote the label rather than
    /// behind a separate query, because a warning that has to be asked for is
    /// not a warning.
    pub fn deciders_resembling(&self, human: &str) -> Result<Vec<String>> {
        let known = self.store.recorded_deciders()?;
        Ok(resembling_deciders(human, known.iter().map(String::as_str)))
    }

    /// Human acceptance — the attributed, guarded human decision *only*
    /// (ADR-0023). The design becomes `accepted` with promotion `pending`; it
    /// does **not** run ADR-0009 code conformance and does **not** invoke a
    /// model or create tasks. Materialising the work is the separate, idempotent
    /// `promote_design` step, so an optional model call never runs inside the
    /// acceptance write. No agent may accept its own design (human-in-the-loop).
    pub fn accept_design(&self, id: &str, human: &str) -> Result<DesignItem> {
        let human = human.trim();
        self.load_for_decision(id, human)?;
        let won =
            self.store
                .decide_design_item(id, DesignStatus::Accepted, human, None, now_unix())?;
        if !won {
            return Err(LodestarError::Invalid(format!(
                "design item {id} was decided concurrently"
            )));
        }
        self.store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))
    }

    /// Return a design whose status nobody ever decided to `proposed`, so it can
    /// be decided properly (ADR-0047).
    ///
    /// This repairs one specific injury: a reconciliation that copied a status
    /// out of an ADR file, leaving `decided_by` empty. Because deciding is
    /// guarded on `proposed`, such a row is otherwise frozen — it asserts a
    /// decision and can never name who made it.
    ///
    /// It is deliberately not an undo. A design with a `decided_by` is a
    /// recorded human act and stays that way; rejecting or superseding it is a
    /// new decision, not the erasure of the old one (ADR-0019).
    pub fn reopen_undecided_design(&self, id: &str) -> Result<DesignItem> {
        let item = self
            .store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
        if item.status == DesignStatus::Proposed {
            return Err(LodestarError::Invalid(format!(
                "design item {id} is already proposed"
            )));
        }
        if item.decided_by.is_some() {
            return Err(LodestarError::Invalid(format!(
                "design item {id} was decided by {}; a recorded decision is not undone here",
                item.decided_by.unwrap_or_default()
            )));
        }
        if !self.store.reopen_undecided_design(id, now_unix())? {
            return Err(LodestarError::Invalid(format!(
                "design item {id} cannot be reopened: it is retired, or its promotion has already materialised work"
            )));
        }
        self.store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))
    }

    /// Record who made a decision the ledger already asserts but attributes to
    /// nobody (ADR-0051).
    ///
    /// This is not a decision — the decision is already there, and work already
    /// descends from it. It records the person behind it, and changes nothing
    /// else. Reserved for rows [`reopen_undecided_design`](Self::reopen_undecided_design)
    /// must refuse: once promotion has materialised work, reopening would leave
    /// tasks descending from a decision the ledger no longer shows, which left
    /// those rows asserting a decision that could never be attributed.
    pub fn attribute_design_decision(&self, id: &str, human: &str) -> Result<DesignItem> {
        let human = human.trim();
        if human.is_empty() {
            return Err(LodestarError::Invalid(
                "attributing a decision requires the person who made it".to_string(),
            ));
        }
        let item = self
            .store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
        if let Some(decider) = item.decided_by.as_deref() {
            return Err(LodestarError::Invalid(format!(
                "design item {id} is already attributed to {decider}; a recorded human act is not rewritten here"
            )));
        }
        if item.status == DesignStatus::Proposed {
            return Err(LodestarError::Invalid(format!(
                "design item {id} is proposed and asserts no decision yet; accept or reject it instead"
            )));
        }
        if item.promotion_status == DesignPromotionStatus::NotRequired {
            return Err(LodestarError::Invalid(format!(
                "design item {id} has materialised no work, so it can still be decided properly; reopen_undecided_design then accept or reject it"
            )));
        }
        if !self
            .store
            .attribute_design_decision(id, human, now_unix())?
        {
            return Err(LodestarError::Invalid(format!(
                "design item {id} was attributed concurrently"
            )));
        }
        self.store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))
    }

    /// Human rejection — durable and auditable (archive-not-delete); spawns no
    /// work. Requires a rationale.
    pub fn reject_design(&self, id: &str, human: &str, reason: &str) -> Result<DesignItem> {
        if reason.trim().is_empty() {
            return Err(LodestarError::Invalid(
                "a rejection reason is required".to_string(),
            ));
        }
        let human = human.trim();
        self.load_for_decision(id, human)?;
        let won = self.store.decide_design_item(
            id,
            DesignStatus::Rejected,
            human,
            Some(reason),
            now_unix(),
        )?;
        if !won {
            return Err(LodestarError::Invalid(format!(
                "design item {id} was decided concurrently"
            )));
        }
        self.store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))
    }

    /// Load a design item and enforce the human-decision guards: a non-empty
    /// human identity that is not the proposing agent (human-in-the-loop), and an
    /// item still open to a decision.
    fn load_for_decision(&self, id: &str, human: &str) -> Result<DesignItem> {
        if human.is_empty() {
            return Err(LodestarError::Invalid(
                "a human decider identity is required".to_string(),
            ));
        }
        let item = self
            .store
            .get_design_item(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
        // Human-in-the-loop: the agent that proposed a design may not decide it.
        if item.proposed_by.as_deref() == Some(human) {
            return Err(LodestarError::Invalid(
                "an agent may not decide its own design item; a human reviewer must accept or reject it"
                    .to_string(),
            ));
        }
        if !item.status.is_open() {
            return Err(LodestarError::Invalid(format!(
                "design item {id} is already {}; only a proposed item can be decided",
                item.status.as_str()
            )));
        }
        if item.deferred.is_some() {
            return Err(LodestarError::Invalid(format!(
                "design item {id} is deferred; resume it before deciding it"
            )));
        }
        if item.retired.is_some() || item.superseded.is_some() {
            return Err(LodestarError::Invalid(format!(
                "design item {id} is not a live proposal"
            )));
        }
        Ok(item)
    }
}

#[cfg(test)]
mod tests {
    use crate::design::{
        DesignConstraintDraft, DesignMaterializationMode, DesignMaterializationPlan,
        DesignMetadata, DesignTaskDraft,
    };
    use crate::facade::test_support::engine;
    use crate::{DesignPromotionStatus, DesignStatus, GoalKind, Lodestar, LodestarError};

    fn agent_engine(agent: &str) -> Lodestar {
        let _ = agent;
        engine()
    }

    /// The ledger read that makes the comparison possible: a new label is
    /// checked against the ones already recorded, which is the only evidence
    /// available for an identity nothing can authenticate.
    #[test]
    fn a_new_decider_is_compared_against_the_ones_already_recorded() {
        let e = engine();
        let decided = e
            .register_design("docs/adr/0001-first.md", "First", "", None)
            .unwrap();
        e.accept_design(&decided.id, "monk-eee").unwrap();

        // One deletion from the label seventy rows already carry.
        assert_eq!(e.deciders_resembling("monk-ee").unwrap(), vec!["monk-eee"]);
        // The normal case, and a genuinely different reviewer, both stay quiet.
        assert!(e.deciders_resembling("monk-eee").unwrap().is_empty());
        assert!(e.deciders_resembling("alice").unwrap().is_empty());
    }

    #[test]
    fn nothing_resembles_anything_in_an_empty_ledger() {
        assert!(engine().deciders_resembling("monk-eee").unwrap().is_empty());
    }

    fn create_plan(goal_id: &str, title: &str) -> DesignMaterializationPlan {
        DesignMaterializationPlan {
            mode: DesignMaterializationMode::Create,
            tasks: vec![DesignTaskDraft {
                goal_id: goal_id.to_string(),
                title: title.to_string(),
                acceptance: "reviewed acceptance".to_string(),
            }],
            task_ids: Vec::new(),
            constraints: Vec::new(),
            rationale: None,
        }
    }

    #[test]
    fn accept_marks_pending_and_promote_materialises_tasks_idempotently() {
        let e = agent_engine("planner");
        let item = e
            .register_design(
                "docs/adr/0023-design-board-accept-bridge.md",
                "Accept bridge",
                "human accept completes design work",
                Some("planner"),
            )
            .unwrap();
        assert_eq!(item.id, "design:0023-design-board-accept-bridge");
        assert_eq!(item.status, DesignStatus::Proposed);
        assert_eq!(item.promotion_status, DesignPromotionStatus::NotRequired);
        assert_eq!(item.proposed_by.as_deref(), Some("planner"));
        assert_eq!(e.design_board().unwrap().len(), 1);

        // Accept is the human decision only: no code conformance, no tasks yet,
        // promotion armed `pending`.
        let accepted = e.accept_design(&item.id, "human-reviewer").unwrap();
        assert_eq!(accepted.status, DesignStatus::Accepted);
        assert_eq!(accepted.decided_by.as_deref(), Some("human-reviewer"));
        assert_eq!(accepted.promotion_status, DesignPromotionStatus::Pending);
        assert!(e.next_task().unwrap().is_none());
        assert_eq!(e.design_board().unwrap(), vec![accepted.clone()]);
        assert!(e.design_promotion(&item.id).unwrap().is_none());

        // The human selects an objective, reviews the plan, then materialises it.
        let objective = e
            .define_goal(GoalKind::Objective, "Ship the bridge", "wire it", None)
            .unwrap();
        let plan = e.plan_design_promotion(&item.id, &objective.id).unwrap();
        assert!(e.next_task().unwrap().is_none());
        let promo = e.promote_design(&item.id, &plan).unwrap();
        assert_eq!(
            promo.item.promotion_status,
            DesignPromotionStatus::Materialized
        );
        assert_eq!(promo.goals[0].id, objective.id);
        assert!(!promo.tasks.is_empty());
        assert!(promo.tasks.iter().all(|t| t.goal_id == objective.id));
        assert_eq!(e.next_task().unwrap().unwrap().goal_id, objective.id);
        assert!(e.design_board().unwrap().is_empty());
        let persisted = e.design_promotion(&item.id).unwrap().unwrap();
        assert_eq!(persisted.goals[0].id, promo.goals[0].id);
        assert_eq!(
            persisted
                .tasks
                .iter()
                .map(|task| &task.id)
                .collect::<Vec<_>>(),
            promo.tasks.iter().map(|task| &task.id).collect::<Vec<_>>()
        );

        // Idempotent: a retry returns the same tasks, creating no duplicates.
        let again = e.promote_design(&item.id, &plan).unwrap();
        assert_eq!(
            again.tasks.iter().map(|t| t.id.clone()).collect::<Vec<_>>(),
            promo.tasks.iter().map(|t| t.id.clone()).collect::<Vec<_>>()
        );
        assert_eq!(e.design_materialization_history(&item.id).unwrap().len(), 1);
    }

    #[test]
    fn promote_requires_an_accepted_design_and_an_objective_target() {
        let e = agent_engine("planner");
        let item = e
            .register_design("docs/adr/0031-x.md", "X", "x", Some("planner"))
            .unwrap();
        let objective = e
            .define_goal(GoalKind::Objective, "Obj", "o", None)
            .unwrap();
        // A proposed (not yet accepted) design cannot be planned or promoted.
        assert!(e.plan_design_promotion(&item.id, &objective.id).is_err());
        assert!(e
            .promote_design(&item.id, &create_plan(&objective.id, "Implement X"))
            .is_err());
        e.accept_design(&item.id, "reviewer").unwrap();
        // A constraint goal is not a valid promotion target.
        let constraint = e.define_goal(GoalKind::Constraint, "C", "c", None).unwrap();
        assert!(e
            .promote_design(&item.id, &create_plan(&constraint.id, "Invalid task"))
            .is_err());
    }

    #[test]
    fn an_agent_cannot_decide_its_own_design() {
        let e = agent_engine("planner");
        let item = e
            .register_design(
                "docs/adr/0099-self.md",
                "Self",
                "no self-accept",
                Some("planner"),
            )
            .unwrap();
        let err = e.accept_design(&item.id, "planner").unwrap_err();
        assert!(matches!(err, LodestarError::Invalid(_)));
        // Nothing changed: still proposed, still on the board.
        assert_eq!(e.design_board().unwrap().len(), 1);
    }

    #[test]
    fn a_decided_item_cannot_be_decided_again() {
        let e = agent_engine("planner");
        let item = e
            .register_design("docs/adr/0100-twice.md", "Twice", "", Some("planner"))
            .unwrap();
        e.accept_design(&item.id, "human").unwrap();
        let err = e
            .reject_design(&item.id, "human", "changed my mind")
            .unwrap_err();
        assert!(matches!(err, LodestarError::Invalid(_)));
    }

    #[test]
    fn promote_registers_mandated_constraints_into_the_constitution() {
        let e = agent_engine("planner");
        let item = e
            .register_design(
                "docs/adr/0030-typed-errors.md",
                "Typed errors everywhere",
                "all fallible IO returns a typed error",
                Some("planner"),
            )
            .unwrap();
        e.accept_design(&item.id, "reviewer").unwrap();
        let objective = e
            .define_goal(GoalKind::Objective, "Type the errors", "do it", None)
            .unwrap();
        let mut plan = create_plan(&objective.id, "Type the errors");
        plan.constraints.push(DesignConstraintDraft {
            kind: GoalKind::Constraint,
            title: "No unwrap in prod".to_string(),
            statement: "no unwrap()/expect() on fallible IO outside tests".to_string(),
        });
        let promo = e.promote_design(&item.id, &plan).unwrap();
        // The mandated constraint was registered as a normative goal...
        assert_eq!(promo.constraints.len(), 1);
        assert_eq!(promo.constraints[0].kind, GoalKind::Constraint);
        // ...and it is now part of the active constitution conformance enforces.
        assert!(e
            .get_constitution()
            .unwrap()
            .iter()
            .any(|g| g.title == "No unwrap in prod"));
        // The objective work was materialised alongside it.
        assert!(!promo.tasks.is_empty());
    }

    #[test]
    fn link_and_no_work_materializations_create_no_duplicate_tasks() {
        let e = agent_engine("planner");
        let first_goal = e
            .define_goal(GoalKind::Objective, "Existing graph work", "graph", None)
            .unwrap();
        let second_goal = e
            .define_goal(GoalKind::Objective, "Existing intent work", "intent", None)
            .unwrap();
        let graph_task = e
            .create_task(&first_goal.id, "Existing graph task", "done")
            .unwrap();
        let intent_task = e
            .create_task(&second_goal.id, "Existing intent task", "done")
            .unwrap();
        let item = e
            .register_design(
                "docs/adr/0103-link.md",
                "Link",
                "reuse existing work",
                Some("planner"),
            )
            .unwrap();
        e.accept_design(&item.id, "reviewer").unwrap();
        let linked = e
            .promote_design(
                &item.id,
                &DesignMaterializationPlan {
                    mode: DesignMaterializationMode::Link,
                    tasks: Vec::new(),
                    task_ids: vec![graph_task.id.clone(), intent_task.id.clone()],
                    constraints: Vec::new(),
                    rationale: Some("These tasks already implement the decision".into()),
                },
            )
            .unwrap();
        assert_eq!(linked.tasks.len(), 2);
        assert_eq!(linked.goals.len(), 2);
        assert_eq!(e.board(false).unwrap().len(), 2);

        let no_work = e
            .register_design(
                "docs/adr/0104-no-work.md",
                "No work",
                "policy only",
                Some("planner"),
            )
            .unwrap();
        e.accept_design(&no_work.id, "reviewer").unwrap();
        let resolved = e
            .promote_design(
                &no_work.id,
                &DesignMaterializationPlan {
                    mode: DesignMaterializationMode::NoWork,
                    tasks: Vec::new(),
                    task_ids: Vec::new(),
                    constraints: Vec::new(),
                    rationale: Some("Existing behavior already conforms".into()),
                },
            )
            .unwrap();
        assert!(resolved.tasks.is_empty());
        assert!(resolved.goals.is_empty());
        assert_eq!(e.board(false).unwrap().len(), 2);
    }

    #[test]
    fn repair_relinks_current_work_and_keeps_append_only_history() {
        let e = agent_engine("planner");
        let goal = e
            .define_goal(GoalKind::Objective, "Repair promotion", "repair", None)
            .unwrap();
        let existing = e
            .create_task(&goal.id, "Authoritative existing task", "done")
            .unwrap();
        let item = e
            .register_design(
                "docs/adr/0105-repair.md",
                "Repair",
                "review repair",
                Some("planner"),
            )
            .unwrap();
        e.accept_design(&item.id, "reviewer").unwrap();
        let first = e
            .promote_design(&item.id, &create_plan(&goal.id, "Generated duplicate"))
            .unwrap();
        let duplicate_id = first.tasks[0].id.clone();
        let repair = DesignMaterializationPlan {
            mode: DesignMaterializationMode::Link,
            tasks: Vec::new(),
            task_ids: vec![existing.id.clone()],
            constraints: Vec::new(),
            rationale: Some("The reviewed work already existed".into()),
        };
        let revised = e
            .revise_design_promotion(&item.id, "second-reviewer", &repair)
            .unwrap();
        assert_eq!(revised.revision, 2);
        assert_eq!(revised.tasks[0].id, existing.id);
        assert!(e
            .board(true)
            .unwrap()
            .iter()
            .any(|task| task.id == duplicate_id));
        assert_eq!(e.design_materialization_history(&item.id).unwrap().len(), 2);

        let retry = e
            .revise_design_promotion(&item.id, "second-reviewer", &repair)
            .unwrap();
        assert_eq!(retry.revision, 2);
        assert_eq!(e.design_materialization_history(&item.id).unwrap().len(), 2);
    }

    #[test]
    fn reject_requires_a_reason_and_stays_durable() {
        let e = agent_engine("planner");
        let item = e
            .register_design("docs/adr/0101-reject.md", "Reject", "", Some("planner"))
            .unwrap();
        assert!(e.reject_design(&item.id, "human", "  ").is_err());
        let rejected = e
            .reject_design(&item.id, "human", "superseded by 0102")
            .unwrap();
        assert_eq!(rejected.status, DesignStatus::Rejected);
        assert_eq!(rejected.reason.as_deref(), Some("superseded by 0102"));
        // Archive-not-delete: off the board but still present.
        assert!(e.design_board().unwrap().is_empty());
        assert_eq!(e.list_design_items(None, false, false).unwrap().len(), 1);
    }

    #[test]
    fn defer_and_resume_are_attributed_acts_without_changing_status() {
        let e = agent_engine("planner");
        let item = e
            .register_design(
                "docs/adr/0077-crowded-board.md",
                "A crowded board is not a decision",
                "park stale proposals honestly",
                Some("planner"),
            )
            .unwrap();

        assert!(e.defer_design(&item.id, "reviewer", " ").is_err());
        assert!(e.defer_design(&item.id, "planner", "not now").is_err());
        let deferred = e.defer_design(&item.id, "reviewer", "not now").unwrap();
        assert_eq!(deferred.status, DesignStatus::Proposed);
        assert_eq!(deferred.deferred.as_ref().unwrap().by, "reviewer");
        assert!(e.design_board().unwrap().is_empty());
        assert!(e.list_design_items(None, false, false).unwrap().is_empty());
        assert_eq!(
            e.list_design_items(None, false, true).unwrap(),
            vec![deferred]
        );

        assert!(e.resume_design(&item.id, "", "back in scope").is_err());
        assert!(e.resume_design(&item.id, "reviewer", " ").is_err());
        let resumed = e
            .resume_design(&item.id, "reviewer", "back in scope")
            .unwrap();
        assert!(resumed.deferred.is_none());
        assert_eq!(e.design_board().unwrap(), vec![resumed]);
    }

    #[test]
    fn a_deferred_proposal_must_be_resumed_before_it_can_be_decided() {
        let e = agent_engine("planner");
        let item = e
            .register_design(
                "docs/adr/0077-deferred.md",
                "Deferred",
                "not currently under review",
                Some("planner"),
            )
            .unwrap();
        e.defer_design(&item.id, "reviewer", "not now").unwrap();

        let error = e.accept_design(&item.id, "reviewer").unwrap_err();
        assert!(error.to_string().contains("deferred"), "{error}");
        let still_deferred = e
            .list_design_items(Some(DesignStatus::Proposed), false, true)
            .unwrap();
        assert_eq!(still_deferred.len(), 1);
        assert!(still_deferred[0].deferred.is_some());

        e.resume_design(&item.id, "reviewer", "ready now").unwrap();
        assert_eq!(
            e.accept_design(&item.id, "reviewer").unwrap().status,
            DesignStatus::Accepted
        );
    }

    #[test]
    fn registering_the_same_adr_twice_is_rejected() {
        let e = agent_engine("planner");
        e.register_design("docs/adr/0102-dup.md", "Dup", "", Some("planner"))
            .unwrap();
        let err = e
            .register_design("docs/adr/0102-dup.md", "Dup again", "", Some("planner"))
            .unwrap_err();
        assert!(matches!(err, LodestarError::Invalid(_)));
    }

    #[test]
    fn reconciliation_imports_history_without_scheduling_or_overwriting_decisions() {
        let e = agent_engine("workspace-sensor");
        let entries = vec![
            DesignMetadata {
                adr_path: "docs\\adr\\0026-constitution.md".into(),
                title: "Constitution".into(),
                summary: "review governance".into(),
                status: DesignStatus::Proposed,
                proposed_by: Some("planner".into()),
            },
            DesignMetadata {
                adr_path: "docs/adr/0001-historical.md".into(),
                title: "Historical".into(),
                summary: String::new(),
                status: DesignStatus::Accepted,
                proposed_by: None,
            },
            DesignMetadata {
                adr_path: "docs/adr/0002-rejected.md".into(),
                title: "Rejected".into(),
                summary: String::new(),
                status: DesignStatus::Rejected,
                proposed_by: None,
            },
        ];

        let reconciled = e.reconcile_designs(&entries).unwrap();
        assert_eq!(reconciled.len(), 3);
        assert_eq!(reconciled[0].adr_path, "docs/adr/0026-constitution.md");
        assert!(reconciled
            .iter()
            .all(|item| item.promotion_status == DesignPromotionStatus::NotRequired));
        assert_eq!(e.design_board().unwrap(), vec![reconciled[0].clone()]);
        assert!(e.next_task().unwrap().is_none());

        let accepted = e.accept_design(&reconciled[0].id, "reviewer").unwrap();
        let retry = e
            .reconcile_designs(&[DesignMetadata {
                status: DesignStatus::Rejected,
                title: "Must not overwrite".into(),
                ..entries[0].clone()
            }])
            .unwrap();
        // The edited ADR title lands, but acceptance and promotion state do not
        // regress to whatever the repository file happens to declare.
        assert_eq!(retry.len(), 1);
        assert_eq!(retry[0].title, "Must not overwrite");
        assert_eq!(retry[0].status, accepted.status);
        assert_eq!(retry[0].decided_by, accepted.decided_by);
        assert_eq!(retry[0].promotion_status, accepted.promotion_status);
        assert_eq!(e.design_board().unwrap(), retry);
        assert!(e.next_task().unwrap().is_none());
    }
}
